enum { SURFER_LAST = 14, BEACH_MAVERICKS = 6 };

class game
{
public:
	int get_beach_id() const;
};

extern game *g_game_ptr;

class JudgingSystem
{
public:
	enum { NUM_COMPETITORS = 9 };

	struct RUN
	{
		float regionScores[3];

		float GetAverageScore(void) const
		{
			if (g_game_ptr->get_beach_id() != BEACH_MAVERICKS)
				return (regionScores[0]+regionScores[1]+regionScores[2])/3.0f;
			else
				return (regionScores[0]+regionScores[1])/2.0f;
		}
	};

	struct RESULT
	{
		RUN runs[3];
		int rank;

		float GetRunTotal(void) const { return runs[0].GetAverageScore() + runs[1].GetAverageScore() + runs[2].GetAverageScore(); }
	};

protected:
	float skills[SURFER_LAST];
	bool isCompetitor[SURFER_LAST];
	float difficulties[3];
	RESULT results[SURFER_LAST];
	int currRunIdx;
	bool over;
	int numPlayerWipeouts;

	void CalcRank(void);
};

void JudgingSystem::CalcRank(void)
{
	int	i;

	// Reset ranks.
	for (i = 0; i < SURFER_LAST; i++)
		results[i].rank = 0;

	// Compute each surfer's rank.
	for (int rank = 1; rank <= NUM_COMPETITORS; rank++)
	{
		int largestIdx = -1;
		for (i = 0; i < SURFER_LAST; i++)
		{
			// Ignore invalid surfers.
			if (!isCompetitor[i]) continue;

			if (results[i].rank == 0)
			{
				if (largestIdx == -1 || results[i].GetRunTotal() > results[largestIdx].GetRunTotal())
					largestIdx = i;
			}
		}

		results[largestIdx].rank = rank;
	}
}
